<html lang="el"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ιστορικό κύκλου ζωής</title><style>body{margin:0;font-family:system-ui,sans-serif;background:#f1f5f9;color:#172033}main{max-width:1050px;margin:auto;padding:28px 16px}.card{background:white;border-radius:12px;box-shadow:0 1px 4px #0f172a18;overflow:hidden}h1{margin:12px 0 3px}p{color:#64748b}a{color:#155e75;text-decoration:none;font-weight:650}table{width:100%;border-collapse:collapse}th,td{border-bottom:1px solid #e2e8f0;padding:12px;text-align:left;vertical-align:top;font-size:.92rem}th{background:#f8fafc;color:#475569}.pill{display:inline-block;background:#e0f2fe;color:#075985;border-radius:999px;padding:4px 8px;font-size:.8rem}@media(max-width:700px){.hide-mobile{display:none}th,td{padding:8px;font-size:.8rem}}</style></head><body><main><a href="{{ url('/admin/assets') }}">← Πάγια</a><h1>{{ $asset->asset_code }} — {{ $asset->name }}</h1><p>Τρέχουσα κατάσταση: <strong>{{ \App\Models\AssetStatusTransaction::STATUSES[$asset->status] ?? $asset->status }}</strong></p><div class="card"><table><thead><tr><th>Ημερομηνία</th><th>Ενέργεια</th><th>Μεταβολή κατάστασης</th><th>Αιτία</th><th class="hide-mobile">Πρωτόκολλο / Έγγραφο</th><th class="hide-mobile">Χρήστης</th></tr></thead><tbody>@forelse($asset->statusTransactions->sortByDesc('id') as $transaction)<tr><td>{{ $transaction->created_at->format('d/m/Y H:i') }}</td><td><span class="pill">{{ \App\Models\AssetStatusTransaction::TYPES[$transaction->transaction_type] ?? $transaction->transaction_type }}</span></td><td>{{ $transaction->from_status ? (\App\Models\AssetStatusTransaction::STATUSES[$transaction->from_status] ?? $transaction->from_status) . ' → ' : '' }} {{ \App\Models\AssetStatusTransaction::STATUSES[$transaction->to_status] ?? $transaction->to_status }}</td><td>{{ $transaction->reason }}</td><td class="hide-mobile">{{ $transaction->document_number ?? '—' }}@if($transaction->document_path)<br><a href="{{ route('asset-transactions.download', $transaction) }}" target="_blank">Άνοιγμα εγγράφου</a>@endif</td><td class="hide-mobile">{{ $transaction->creator?->name ?? '—' }}</td></tr>@empty<tr><td colspan="6">Δεν έχουν καταγραφεί ακόμη συναλλαγές κύκλου ζωής.</td></tr>@endforelse</tbody></table></div></main>@include('filament.partials.contextual-help')</body></html>
